import{_ as n,o as t,c as o,a2 as s}from"./chunks/framework.BN3Eol-0.js";const g=JSON.parse('{"title":"UXD-052 — Booster returns play full frame when the entry burn is sourced (Falcon 9 on a drone ship or at LZ-1, New Glenn on Jacklyn)","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-052-booster-returns-play-full-frame-when-the-entry-burn-is-sourced.md","filePath":"uxs/decisions/UXD-052-booster-returns-play-full-frame-when-the-entry-burn-is-sourced.md"}'),r={name:"uxs/decisions/UXD-052-booster-returns-play-full-frame-when-the-entry-burn-is-sourced.md"};function a(i,e,d,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="uxd-052-—-booster-returns-play-full-frame-when-the-entry-burn-is-sourced-falcon-9-on-a-drone-ship-or-at-lz-1-new-glenn-on-jacklyn" tabindex="-1">UXD-052 — Booster returns play full frame when the entry burn is sourced (Falcon 9 on a drone ship or at LZ-1, New Glenn on Jacklyn) <a class="header-anchor" href="#uxd-052-—-booster-returns-play-full-frame-when-the-entry-burn-is-sourced-falcon-9-on-a-drone-ship-or-at-lz-1-new-glenn-on-jacklyn" aria-label="Permalink to &quot;UXD-052 — Booster returns play full frame when the entry burn is sourced (Falcon 9 on a drone ship or at LZ-1, New Glenn on Jacklyn)&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; unit tests and dev-server screenshots, see Verification; production build, docker-e2e and a real GPU not run, see Not done)</li><li><strong>Date</strong>: 2026-11-24 (proposed) · 2026-11-24 (decided)</li><li><strong>Decider</strong>: the operator, 2026-11-24. The pass-2 redo list (<code>docs/wip/2026-11-24-pass2-redo-list.md</code>, &quot;Pass 2: descents below the standard, redone at the end&quot;) asks for booster landing scenes for Falcon 9 and New Glenn, &quot;with the side thrusters, grid fins and legs modelled and working on the descent&quot;, the Falcon 9 sea landing &quot;on a 3D model of the drone ship, never on open water&quot;; the operator&#39;s order was &quot;finish every batch first, then redo these&quot;. The operator also asked for ESCAPADE and the <code>~</code> mark; a lead agent worked out the camera and the gate below.</li><li><strong>Answers</strong>: 0.9.11 plan row F2 (&quot;Booster landings, more&quot;) as reopened on 2026-11-24, and the pass-2 redo list entry &quot;booster landings&quot;</li><li><strong>Builds on</strong>: <a href="./UXD-050-booster-landing-inset-on-fly">UXD-050</a> (the inset, which this record narrows), <a href="./UXD-046-the-launch-runs-a-seeded-camera-director">UXD-046</a> (the launch light the scene takes)</li><li><strong>Changes</strong>: <a href="./UXD-050-booster-landing-inset-on-fly">UXD-050</a> (marked partly superseded), <a href="./../UXS-003">UXS-003</a> (Booster return, full frame), <code>05_Design_System.md</code> §5.12 (the launch scene), TA.md (Launch / powered ascent), <a href="./../IA">IA</a> §surfaces (<code>/fly</code>), <code>src/lib/three/README.md</code>, <code>src/lib/three/booster-return-scene.ts</code>, <code>src/lib/three/showcase/</code> (<code>falcon9-booster.ts</code>, <code>new-glenn-booster.ts</code>, <code>drone-ship.ts</code>, <code>jacklyn.ts</code>, <code>landing-zone-1.ts</code>), <code>src/lib/components/LaunchScene.svelte</code>, <code>FlightPlan.svelte</code>, <code>src/lib/orbital/flight-plan-beats.ts</code>, <code>src/lib/physics/ascent/ascent-physics.ts</code>, <code>static/data/launch-profiles/falcon-9.json</code>, <code>new-glenn.json</code></li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>UXD-050 drew every recovered booster&#39;s landing as a small inset at the flight&#39;s real time. The operator then asked for the landings to be shown properly: the booster&#39;s whole return, with its grid fins, cold-gas thrusters and legs working, and a Falcon 9 sea landing onto a modelled drone ship rather than open water. A full-size view needs an entry-burn start time as well as a landing time, and the sources give that for only some flights.</p><p>The sourced figures are in <code>docs/wip/2026-11-24-booster-landings-sourced.md</code> and <code>2026-11-24-escapade-sourced.md</code>; IM-1&#39;s in <code>docs/wip/2026-11-24-im1-rtls-sourced.md</code>. Inspiration4&#39;s entry burn at T+450 s, landing burn at T+544 s and touchdown at T+571 s are sourced. IM-1&#39;s whole timeline (entry burn T+6:11 to 6:22, landing burn T+7:17, touchdown T+7:34) comes from an aggregator that cites The Space Devs. ESCAPADE&#39;s New Glenn: entry burn on three of the seven BE-4 about seven minutes in and touchdown on Jacklyn about nine minutes in (Space.com); the landing-burn engine count is unverified.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><ol><li><strong>Keep the inset for every landing (UXD-050).</strong> For: one rule, small frame. Against: the grid fins, the thrusters and the ship cannot be read at 280 px, which is what the operator asked to see. Declined.</li><li><strong>Full frame for every recovered booster.</strong> For: one rule the other way. Against: most flights have no entry-burn time, so the scene would invent the whole descent; Falcon Heavy&#39;s two side boosters and Super Heavy&#39;s tower catch have their own look. Declined.</li><li><strong>Full frame where the entry burn is sourced or &quot;about N minutes&quot;, the inset otherwise.</strong> Chosen.</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Option 3. When a flight&#39;s booster lands on a drone ship, or a Falcon 9&#39;s lands on a landing zone, and its recovery entry carries an entry-burn time (<code>entryBurnS</code>) and a time class of <code>sourced</code> or <code>approx</code>, the landing plays in the whole frame at the real time. A <code>typical</code> time, a Falcon Heavy side booster and a tower catch stay a UXD-050 inset.</p><ol><li><strong>Which flights.</strong> Inspiration4&#39;s Falcon 9 on Just Read the Instructions (JRTI); IM-1&#39;s Falcon 9 returning to Landing Zone 1 (RTLS); ESCAPADE&#39;s New Glenn on Jacklyn. ESCAPADE is a new mission in the catalogue (NASA&#39;s twin Mars orbiters, NG-2, 13 Nov 2025), which makes 141 missions.</li><li><strong>What it shows.</strong> The entry burn on three engines, grid-fin steering with cold-gas puffs, the landing burn on the centre engine, the legs swinging out, and the booster standing on the pad marking of the ship or on the landing zone&#39;s 86 m pad. The models are at real size: the Falcon 9 first stage (nine Merlins, lattice grid fins, folding legs, thruster pods), the drone ship at its real deck size, the New Glenn booster (seven BE-4, six legs, four fins and strakes) and Jacklyn (115.9 x 45.72 m), and Landing Zone 1.</li><li><strong>Camera and light.</strong> The scene is full frame; the sky takes the launch&#39;s light (UXD-046) and turns black above the limb at entry-burn height. The camera frames the booster and the pad together on a short landing burn. The pose and camera are pure functions of mission time, so a scrub is exact.</li><li><strong>Window.</strong> It opens 8 s before the entry burn (<code>RETURN_LEAD_S</code>) and holds 4 s after touchdown (<code>LANDING_HOLD_S</code>) (<code>returnWindow</code>); the upper stage&#39;s telemetry steps aside while it plays, and a caption names the site (<code>data-testid=&quot;booster-return-cap&quot;</code>).</li><li><strong>The <code>~</code>.</strong> A flight-plan row for a landing whose time class is <code>approx</code> or <code>typical</code> prints its time with a leading <code>~</code>.</li><li><strong>What is a sourced figure and what is not.</strong> Entry, landing and touchdown times are the flight&#39;s own where marked <code>sourced</code>. The entry-burn length, every altitude and speed, the thruster pattern, the attitude wobble, the camera work, the New Glenn landing-burn engine count and the IM-1 coast distance are estimates, listed in the scene&#39;s header comment.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>UXD-050&#39;s inset stays for tower catches, Falcon Heavy side boosters and any landing without an entry-burn time. UXD-050 is marked partly superseded for drone-ship and landing-zone landings with a sourced entry burn.</li><li><code>LaunchScene.svelte</code> chooses between <code>createBoosterReturn</code> and the inset (<code>returnLanding</code> gate); <code>ascent-renderer.ts</code> draws the return scene as a full-frame view.</li><li>Recovery data grows <code>entryBurnS</code> and <code>entryBurnEndS</code>; Inspiration4&#39;s recovery entry was also corrected from OCISLY to JRTI (a data defect fix).</li><li>The mission count is 141. The 14-locale mission overlays, the hero and the card for ESCAPADE shipped with the mission; its delta-v tile reads &quot;Not published&quot;.</li><li>Falcon 9 legs deploy to about 29 degrees so the feet sit about 1.5 m under the bells.</li><li>It rules out a full-frame landing for a flight whose entry burn is not published; adding one is a data entry, not a new decision.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Unit tests: <code>src/lib/three/booster-return-scene.test.ts</code> (pose, window, both launchers), <code>flight-plan-beats.test.ts</code> (the <code>~</code>), <code>recovery.test.ts</code>, <code>ascent-physics</code> recovery entries. Dev-server screenshots read at 1280 and 375 px for the three flights.</p><h2 id="not-done" tabindex="-1">Not done <a class="header-anchor" href="#not-done" aria-label="Permalink to &quot;Not done&quot;">​</a></h2><ul><li>Frame time on a real GPU or phone is not measured; the production build and docker-e2e have not run on this change.</li><li>Altitudes, speeds and the thruster pattern are estimates; no source gives them.</li><li>ESCAPADE&#39;s landing-burn engine count (one BE-4) and the Blue Origin timeline come from a search snippet, not a read page; JRTI&#39;s and IM-1&#39;s times are from third-party mirrors of SpaceX&#39;s own figures.</li><li>Starship&#39;s tower catch has no full-frame return; Falcon Heavy side boosters keep the inset.</li><li>IM-1&#39;s aggregator times (<code>2026-11-24-im1-rtls-sourced.md</code>) are not cross-checked against SpaceX&#39;s own webcast timeline.</li></ul>',16)])])}const p=n(r,[["render",a]]);export{g as __pageData,p as default};
